import type { Artifact, CommentThread as CommentThreadData } from '@artifact-hub/shared';
import { useId, useState } from 'react';
import { Link } from 'react-router';
import { InlineError, InlineLoading } from '@/components/inline-status.tsx';
import { Badge } from '@/components/ui/badge.tsx';
import { Button } from '@/components/ui/button.tsx';
import { cn } from '@/lib/utils';
import { CommentForm } from './comment-form.tsx';
import { CommentThread } from './comment-thread.tsx';
import type { FeedbackFilter } from './comments.types.ts';
import { useCommentThreads, useCreateComment } from './use-comments.ts';

/**
 * The Feedback tab: a box to add a comment for those who may comment, then the comments on the
 * version being viewed (`versionNo`) or on every version, resolved or not, oldest first.
 * `versionNo` is null when no version is shown; all comments are listed then.
 */
export function FeedbackPanel({
  artifact,
  versionNo,
}: {
  artifact: Artifact;
  versionNo: number | null;
}) {
  const [filter, setFilter] = useState<FeedbackFilter>('version');
  const shownVersionNo = filter === 'version' ? versionNo : null;
  const {
    data: threads,
    error,
    refetch,
    isPlaceholderData,
  } = useCommentThreads(artifact.id, shownVersionNo);
  const create = useCreateComment(artifact.id);
  const canComment = artifact.permissions.comment;
  const filterLabelId = useId();

  return (
    <div className="grid gap-4">
      {canComment && versionNo !== null ? (
        <CommentForm
          label="Add a comment"
          placeholder={`Comment on v${versionNo}…`}
          submitLabel="Comment"
          onSubmit={(body) => create.mutateAsync({ body, versionNo })}
        />
      ) : !canComment ? (
        <p className="text-sm text-muted-foreground">You can read the comments, but not add any.</p>
      ) : null}

      {versionNo !== null ? (
        <div className="grid gap-1.5">
          <span id={filterLabelId} className="text-xs font-medium text-muted-foreground">
            Show feedback for:
          </span>
          <div
            role="group"
            aria-labelledby={filterLabelId}
            className="flex rounded-md border p-0.5"
          >
            {(['version', 'all'] as const).map((option) => (
              <Button
                key={option}
                variant={filter === option ? 'secondary' : 'ghost'}
                size="xs"
                className="flex-1"
                aria-pressed={filter === option}
                onClick={() => setFilter(option)}
              >
                {option === 'version' ? `This version (v${versionNo})` : 'All versions'}
              </Button>
            ))}
          </div>
        </div>
      ) : null}

      {error && !threads ? (
        <InlineError error={error} onRetry={() => void refetch()} />
      ) : !threads ? (
        <div className="h-24">
          <InlineLoading />
        </div>
      ) : (
        <ThreadList
          artifact={artifact}
          threads={threads}
          showVersions={shownVersionNo === null}
          emptyText={
            shownVersionNo === null ? 'No comments yet.' : `No comments on v${shownVersionNo} yet.`
          }
          className={cn('transition-opacity', isPlaceholderData && 'opacity-60')}
        />
      )}
    </div>
  );
}

function ThreadList({
  artifact,
  threads,
  showVersions,
  emptyText,
  className,
}: {
  artifact: Artifact;
  threads: CommentThreadData[];
  /** Label each thread with its version, linking to it. */
  showVersions: boolean;
  emptyText: string;
  className?: string;
}) {
  if (threads.length === 0) {
    return <p className="text-sm text-muted-foreground">{emptyText}</p>;
  }
  const currentVersionNo = artifact.currentVersion?.versionNo;
  return (
    <ol className={cn('grid gap-3', className)} aria-label="Comments">
      {threads.map((thread) => (
        <CommentThread
          key={thread.id}
          artifactId={artifact.id}
          thread={thread}
          canReply={artifact.permissions.comment}
          badges={
            showVersions ? (
              <Badge asChild variant="outline">
                <Link
                  to={
                    thread.versionNo === currentVersionNo
                      ? `/artifacts/${artifact.id}`
                      : `/artifacts/${artifact.id}?v=${thread.versionNo}`
                  }
                  aria-label={`On version ${thread.versionNo}`}
                >
                  v{thread.versionNo}
                </Link>
              </Badge>
            ) : null
          }
        />
      ))}
    </ol>
  );
}
import {
  type Comment,
  type CommentThread,
  commentListResponseSchema,
  commentResponseSchema,
  type CreateCommentRequest,
  type UpdateCommentRequest,
} from '@artifact-hub/shared';
import { artifactQueryKey } from '@/features/artifacts/artifacts-api.ts';
import { apiRequest } from '@/lib/api/client.ts';

/** Under the artifact's key, so they go with the artifact's other queries. */
export const commentsQueryKey = (artifactId: string) =>
  [...artifactQueryKey(artifactId), 'comments'] as const;
/** One version's threads, or every version's (`versionNo` null). */
export const commentThreadsQueryKey = (artifactId: string, versionNo: number | null) =>
  [...commentsQueryKey(artifactId), versionNo ?? 'all'] as const;

const commentsPath = (artifactId: string) =>
  `/artifacts/${encodeURIComponent(artifactId)}/comments`;
const commentPath = (commentId: string) => `/comments/${encodeURIComponent(commentId)}`;

/** Threads oldest first, resolved ones included; `versionNo` null for every visible version. */
export async function fetchCommentThreads(
  artifactId: string,
  versionNo: number | null,
  signal?: AbortSignal,
): Promise<CommentThread[]> {
  const query = versionNo === null ? '' : `?${new URLSearchParams({ version: String(versionNo) })}`;
  return (
    await apiRequest(`${commentsPath(artifactId)}${query}`, {
      schema: commentListResponseSchema,
      signal,
    })
  ).items;
}

/** With the same `idempotencyKey`, a retry returns the comment the first attempt posted. */
export async function createComment(
  artifactId: string,
  body: CreateCommentRequest,
  idempotencyKey?: string,
): Promise<Comment> {
  return (
    await apiRequest(commentsPath(artifactId), {
      method: 'POST',
      body,
      schema: commentResponseSchema,
      idempotencyKey,
    })
  ).comment;
}

/** Edits the body, or resolves or reopens a top-level comment. Author only. */
export async function updateComment(
  commentId: string,
  body: UpdateCommentRequest,
): Promise<Comment> {
  return (
    await apiRequest(commentPath(commentId), {
      method: 'PATCH',
      body,
      schema: commentResponseSchema,
    })
  ).comment;
}

