  q: z
    .string()
    .trim()
    .min(1, 'Type what you are looking for.')
    .max(ARTIFACT_SEARCH_MAX_LENGTH, `Keep the search to ${ARTIFACT_SEARCH_MAX_LENGTH} characters.`),
  scope: z.enum(ARTIFACT_LIST_SCOPES).default('mine'),
});

