import { ARTIFACT_TYPE_FILTERS, type ArtifactTypeFilter } from '@artifact-hub/shared';
import { Loader2Icon, SearchIcon, XIcon } from 'lucide-react';
import { useEffect, useRef, useState } from 'react';
import { Button } from '@/components/ui/button.tsx';
import { Input } from '@/components/ui/input.tsx';
import { NativeSelect } from '@/components/ui/native-select.tsx';
import { useAppConfig } from '@/features/config/use-app-config.ts';
import { formatUpdatedRange } from '@/lib/format.ts';
import { TYPE_FILTER_LABELS } from './artifact-types.ts';
import type { GalleryFilters as Filters } from './artifacts.types.ts';
import { useArtifactTags, useInterpretSearch } from './use-artifacts.ts';

const TYPE_FILTERS = Object.keys(ARTIFACT_TYPE_FILTERS) as ArtifactTypeFilter[];
const SEARCH_DELAY_MS = 300;

/** Whether `filters` narrow their scope at all. */
export function hasFilters({ q, type, tag, owner, updatedFrom, updatedTo }: Filters): boolean {
  return Boolean(q || type || tag || owner || updatedFrom || updatedTo);
}

/**
 * Search box, type and tag filters for a gallery scope. A search applies once typing pauses,
 * the other filters at once; every change goes through `onChange` (which puts it in the URL).
 * With AI, Enter reads the search as plain language ("the pricing deck Sara shared last week")
 * and replaces the filters with what it asks for; owner and dates show as removable chips.
 */
export function GalleryFilters({
  filters,
  loading,
  onChange,
}: {
  filters: Filters;
  /** Results for the current filters are on their way. */
  loading: boolean;
  onChange: (filters: Filters) => void;
}) {
  const [text, setText] = useState(filters.q ?? '');
  /** A search typed but not applied yet. */
  const [pending, setPending] = useState(false);
  const [shownQ, setShownQ] = useState(filters.q);
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);
  /** Counts searches, so an interpretation arriving after more typing is ignored. */
  const searches = useRef(0);
  const { data: tags } = useArtifactTags(filters.scope);
  const { data: config } = useAppConfig();
  const smart = config?.features.ai ?? false;
  const interpret = useInterpretSearch();

  // The URL's search changed elsewhere (Clear filters, the back button): show it.
  if (filters.q !== shownQ) {
    setShownQ(filters.q);
    if (text.trim() !== (filters.q ?? '')) setText(filters.q ?? '');
  }
  useEffect(() => () => clearTimeout(timer.current), []);

  /** Applies `changes` with whatever is typed, cancelling a search still waiting to apply. */
  const apply = (changes: Partial<Filters>, typed = text) => {
    clearTimeout(timer.current);
    setPending(false);
    onChange({ ...filters, q: typed.trim() || undefined, ...changes });
  };

  const onType = (value: string) => {
    searches.current++;
    setText(value);
    setPending(true);
    clearTimeout(timer.current);
    timer.current = setTimeout(() => apply({}, value), SEARCH_DELAY_MS);
  };

  /** Enter: the search at once, read as plain language when AI is on. */
  const onSubmit = () => {
    const typed = text.trim();
    if (!smart || !typed) return apply({});
    clearTimeout(timer.current);
    const search = ++searches.current;
    setPending(true);
    interpret.mutate(
      { q: typed, scope: filters.scope },
      {
        onSuccess: ({ filters: found }) => {
          if (search !== searches.current) return;
          setPending(false);
          setText(found.q ?? '');
          onChange(found);
        },
        // Couldn't reach the server: search for the words as typed.
        onError: () => {
          if (search === searches.current) apply({}, typed);
        },
      },
    );
  };

  const active = hasFilters(filters);
  const updated = formatUpdatedRange(filters.updatedFrom, filters.updatedTo);
  const chips = [
    filters.owner ? { label: `By ${filters.owner}`, clear: { owner: undefined } } : null,
    updated ? { label: updated, clear: { updatedFrom: undefined, updatedTo: undefined } } : null,
  ].filter((chip) => chip !== null);
  const tagOptions = tags?.map((item) => item.tag) ?? [];
  // A tag from the URL stays selectable even if it isn't among the most used.
  if (filters.tag && !tagOptions.includes(filters.tag)) tagOptions.unshift(filters.tag);

  return (
    <div role="search" className="flex flex-wrap items-center gap-2">
      <div className="relative min-w-56 flex-1">
        {pending || loading ? (
          <Loader2Icon
            className="pointer-events-none absolute top-1/2 left-2.5 size-4 -translate-y-1/2 animate-spin text-muted-foreground"
            aria-hidden="true"
          />
        ) : (
          <SearchIcon
            className="pointer-events-none absolute top-1/2 left-2.5 size-4 -translate-y-1/2 text-muted-foreground"
            aria-hidden="true"
          />
        )}
        <Input
          type="search"
          aria-label="Search"
          placeholder={
            smart
              ? 'Search, or describe what you need and press Enter'
              : 'Search titles, tags and descriptions'
          }
          className="pl-8"
          value={text}
          onChange={(event) => onType(event.target.value)}
          onKeyDown={(event) => {
            if (event.key !== 'Enter' || event.nativeEvent.isComposing) return;
            event.preventDefault();
            onSubmit();
          }}
        />
      </div>
      <NativeSelect
        aria-label="Type"
        value={filters.type ?? ''}
        onChange={(event) => apply({ type: (event.target.value || undefined) as Filters['type'] })}

