  describe('AI summary', () => {
    const summaryRegion = () => screen.findByRole('region', { name: 'AI summary' });

    it('summarizes the comments shown on request', async () => {
      api.enableAi();
      const item = artifactWithVersions();
      const header = api.addComment(item.id, grace, 'The header is too big');
      api.summarizeWith({
        overview: 'Reviewers want a smaller header.',
        themes: [
          {
            title: 'Header size',
            summary: 'It takes too much room.',
            sentiment: 'negative',
            status: 'open',
            commentIds: [header],
          },
        ],
        disagreements: [{ topic: 'Colors', summary: 'Blue or green.', commentIds: [] }],
      });
      const { user } = open(item);

      const region = await summaryRegion();
      await user.click(within(region).getByRole('button', { name: 'Summarize feedback' }));
      expect(await within(region).findByText('Reviewers want a smaller header.')).toBeTruthy();
      const theme = within(within(region).getByRole('list', { name: 'Themes' })).getByRole(
        'listitem',
      );
      expect(theme.textContent).toBe('Header sizeOpenConcernsIt takes too much room.From 1 comment');
      expect(within(region).getByText('Colors:')).toBeTruthy();
      expect(within(region).getByText(/^Written by AI just now from 1 comment\\./)).toBeTruthy();
      expect(within(region).queryByRole('button')).toBeNull();
    });

    it('marks the summary outdated when comments change, and writes it again', async () => {
      api.enableAi();
      const item = artifactWithVersions();
      api.addComment(item.id, grace, 'The header is too big');
      const { user } = open(item);
      const region = await summaryRegion();
      await user.click(within(region).getByRole('button', { name: 'Summarize feedback' }));
      await within(region).findByText('Reviewers like it overall.');

      await user.type(screen.getByRole('textbox', { name: 'Add a comment' }), 'Agreed');
      await user.click(screen.getByRole('button', { name: 'Comment' }));
      expect(await within(region).findByText('Outdated')).toBeTruthy();

      await user.click(within(region).getByRole('button', { name: 'Refresh' }));
      await waitFor(() => expect(within(region).queryByText('Outdated')).toBeNull());
      expect(within(region).getByText(/from 2 comments/)).toBeTruthy();
      expect(api.summarizeCount).toBe(2);
    });

    it('follows the version filter', async () => {
      api.enableAi();
      const item = artifactWithVersions();
      api.addComment(item.id, grace, 'On v2');
      const { user } = open(item);
      const region = await summaryRegion();
      await user.click(within(region).getByRole('button', { name: 'Summarize feedback' }));
      await within(region).findByText('Reviewers like it overall.');

      await user.click(screen.getByRole('button', { name: 'All versions' }));
      expect(
        await within(await summaryRegion()).findByRole('button', { name: 'Summarize feedback' }),
      ).toBeTruthy();
    });

    it('says when it could not summarize', async () => {
      api.enableAi();
      api.summarizeWith(new Error("Couldn't summarize the feedback right now."));
      const item = artifactWithVersions();
      api.addComment(item.id, grace, 'Hello');
      const { user } = open(item);
      const region = await summaryRegion();
      await user.click(within(region).getByRole('button', { name: 'Summarize feedback' }));
      expect((await within(region).findByRole('alert')).textContent).toBe(
        "Couldn't summarize the feedback right now.",
      );
    });

    it('is not offered without AI, nor without comments', async () => {
      const item = artifactWithVersions();
      api.addComment(item.id, grace, 'Hello');
      open(item);
      await thread('Grace Hopper');
      expect(screen.queryByRole('region', { name: 'AI summary' })).toBeNull();
      cleanup();

      api.enableAi();
      open(artifactWithVersions());
      expect(await screen.findByText('No comments on v2 yet.')).toBeTruthy();
      expect(screen.queryByRole('region', { name: 'AI summary' })).toBeNull();
    });
  });
});
"""
open(p,'w').write(s)
