1	import type {
2	  FeedbackSentiment,
3	  FeedbackSummary as Summary,
4	  FeedbackThemeStatus,
5	} from '@artifact-hub/shared';
6	import { Loader2Icon, RefreshCwIcon, SparklesIcon } from 'lucide-react';
7	import { Badge } from '@/components/ui/badge.tsx';
8	import { Button } from '@/components/ui/button.tsx';
9	import { useAppConfig } from '@/features/config/use-app-config.ts';
10	import { describeError, isApiError } from '@/lib/api/api-error.ts';
11	import { formatRelativeTime } from '@/lib/format.ts';
12	import { useFeedbackSummary, useSummarizeFeedback } from './use-comments.ts';
13	
14	const STATUS_LABELS: Record<FeedbackThemeStatus, string> = {
15	  open: 'Open',
16	  resolved: 'Resolved',
17	  mixed: 'Partly resolved',
18	};
19	
20	const SENTIMENT_LABELS: Record<FeedbackSentiment, string> = {
21	  positive: 'Positive',
22	  negative: 'Concerns',
23	  mixed: 'Mixed',
24	  neutral: 'Neutral',
25	};
26	
27	/**
28	 * The AI summary of the comments shown: one version's (`versionNo`) or every version's (null).
29	 * Written on request and saved; when comments change it is marked outdated, with a button to
30	 * write it again. Hidden without AI, and while there are no comments.
31	 */
32	export function FeedbackSummary({
33	  artifactId,
34	  versionNo,
35	  hasComments,
36	}: {
37	  artifactId: string;
38	  versionNo: number | null;
39	  hasComments: boolean;
40	}) {
41	  const { data: config } = useAppConfig();
42	  const enabled = (config?.features.ai ?? false) && hasComments;
43	  const { data } = useFeedbackSummary(artifactId, versionNo, { enabled });
44	  const summarize = useSummarizeFeedback(artifactId, versionNo);
45	  if (!enabled || !data) return null;
46	
47	  const { summary, outdated } = data;
48	  const busy = summarize.isPending;
49	  const action =
50	    !summary || outdated ? (
51	      <Button
52	        variant={summary ? 'ghost' : 'outline'}
53	        size="sm"
54	        disabled={busy}
55	        onClick={() => summarize.mutate()}
56	      >
57	        {busy ? (
58	          <Loader2Icon className="animate-spin" aria-hidden="true" />
59	        ) : summary ? (
60	          <RefreshCwIcon aria-hidden="true" />
61	        ) : (
62	          <SparklesIcon aria-hidden="true" />
63	        )}
64	        {busy ? 'Summarizing…' : summary ? 'Refresh' : 'Summarize feedback'}
65	      </Button>
66	    ) : null;
67	
68	  return (
69	    <section aria-label="AI summary" className="grid gap-3 rounded-lg border bg-muted/40 p-3">
70	      <header className="flex flex-wrap items-center gap-2">
71	        <h3 className="flex items-center gap-1.5 text-sm font-medium">
72	          <SparklesIcon className="size-4 text-muted-foreground" aria-hidden="true" />
73	          AI summary
74	        </h3>
75	        {summary && outdated ? <Badge variant="outline">Outdated</Badge> : null}
76	        <span className="ml-auto">{action}</span>
77	      </header>
78	
79	      {summarize.error ? (
80	        <p role="alert" className="text-sm text-destructive">
81	          {isApiError(summarize.error, 'AI_UNAVAILABLE')
82	            ? summarize.error.message
83	            : describeError(summarize.error)}
84	        </p>
85	      ) : null}
86	
87	      {summary ? (
88	        <SummaryBody summary={summary} />
89	      ) : (
90	        <p className="text-sm text-muted-foreground">
91	          {busy
92	            ? 'Reading the comments… this can take up to a minute.'
93	            : 'Get the main themes, what is still open and where reviewers disagree.'}
94	        </p>
95	      )}
96	    </section>
97	  );
98	}
99	
100	function SummaryBody({ summary }: { summary: Summary }) {
101	  return (
102	    <div className="grid gap-3 text-sm">
