import type {
  FeedbackSentiment,
  FeedbackSummary as Summary,
  FeedbackThemeStatus,
} from '@artifact-hub/shared';
import { Loader2Icon, RefreshCwIcon, SparklesIcon } from 'lucide-react';
import { Badge } from '@/components/ui/badge.tsx';
import { Button } from '@/components/ui/button.tsx';
import { useAppConfig } from '@/features/config/use-app-config.ts';
import { describeError, isApiError } from '@/lib/api/api-error.ts';
import { formatRelativeTime } from '@/lib/format.ts';
import { useFeedbackSummary, useSummarizeFeedback } from './use-comments.ts';

const STATUS_LABELS: Record<FeedbackThemeStatus, string> = {
  open: 'Open',
  resolved: 'Resolved',
  mixed: 'Partly resolved',
};

const SENTIMENT_LABELS: Record<FeedbackSentiment, string> = {
  positive: 'Positive',
  negative: 'Concerns',
  mixed: 'Mixed',
  neutral: 'Neutral',
};

/**
 * The AI summary of the comments shown: one version's (`versionNo`) or every version's (null).
 * Written on request and saved; when comments change it is marked outdated, with a button to
 * write it again. Hidden without AI, and while there are no comments.
 */
export function FeedbackSummary({
  artifactId,
  versionNo,
  hasComments,
}: {
  artifactId: string;
  versionNo: number | null;
  hasComments: boolean;
}) {
  const { data: config } = useAppConfig();
  const enabled = (config?.features.ai ?? false) && hasComments;
  const { data } = useFeedbackSummary(artifactId, versionNo, { enabled });
  const summarize = useSummarizeFeedback(artifactId, versionNo);
  if (!enabled || !data) return null;

  const { summary, outdated } = data;
  const busy = summarize.isPending;
  const action =
    !summary || outdated ? (
      <Button
        variant={summary ? 'ghost' : 'outline'}
        size="sm"
        disabled={busy}
        onClick={() => summarize.mutate()}
      >
        {busy ? (
          <Loader2Icon className="animate-spin" aria-hidden="true" />
        ) : summary ? (
          <RefreshCwIcon aria-hidden="true" />
        ) : (
          <SparklesIcon aria-hidden="true" />
        )}
        {busy ? 'Summarizing…' : summary ? 'Refresh' : 'Summarize feedback'}
      </Button>
    ) : null;

  return (
    <section aria-label="AI summary" className="grid gap-3 rounded-lg border bg-muted/40 p-3">
      <header className="flex flex-wrap items-center gap-2">
        <h3 className="flex items-center gap-1.5 text-sm font-medium">
          <SparklesIcon className="size-4 text-muted-foreground" aria-hidden="true" />
          AI summary
        </h3>
        {summary && outdated ? <Badge variant="outline">Outdated</Badge> : null}
        <span className="ml-auto">{action}</span>
      </header>

      {summarize.error ? (
        <p role="alert" className="text-sm text-destructive">
          {isApiError(summarize.error, 'AI_UNAVAILABLE')
            ? summarize.error.message
            : describeError(summarize.error)}
        </p>
      ) : null}

      {summary ? (
        <SummaryBody summary={summary} />
      ) : (
        <p className="text-sm text-muted-foreground">
          {busy
            ? 'Reading the comments… this can take up to a minute.'
            : 'Get the main themes, what is still open and where reviewers disagree.'}
        </p>
      )}
    </section>
  );
}

function SummaryBody({ summary }: { summary: Summary }) {
  return (
    <div className="grid gap-3 text-sm">
      <p>{summary.overview}</p>

      {summary.themes.length > 0 ? (
        <ul aria-label="Themes" className="grid gap-2">
          {summary.themes.map((theme, index) => (
            <li key={index} className="grid gap-1 rounded-md border bg-background p-2.5">
              <div className="flex flex-wrap items-center gap-1.5">
                <span className="font-medium">{theme.title}</span>

